            src: [{ path: PJ + "ProjectCapabilityDependencies.java", line: 10, end_line: 25, label: "dependency table" }, { path: PJ + "ProjectCapabilityDependencies.java", line: 28, end_line: 37, label: "direct / resolve" }],
            methods: [{ n: "resolve", purpose: T("Calcula el cierre transitivo de dependencias de un conjunto de áreas.", "Computes the transitive dependency closure of a set of areas."), when: T("Al crear un proyecto, al construir un descriptor y al configurar áreas.", "When creating a project, building a descriptor and configuring areas."), in: T("Set<ProjectCapability> (puede ser nulo o vacío).", "Set<ProjectCapability> (may be null or empty)."), out: T("EnumSet cerrado bajo dependencias.", "EnumSet closed under dependencies."), decisions: T("Bucle de punto fijo: repite hasta que ninguna dependencia nueva se añade.", "Fixed-point loop: repeats until no new dependency is added."), fx: T("ninguno", "none"), fail: T("Nulo o vacío devuelve conjunto vacío.", "Null or empty returns an empty set."), next: T("El descriptor guarda el conjunto.", "The descriptor stores the set."), src: [S(PJ + "ProjectCapabilityDependencies.java", 29)] }],
