            calls: ["prj_dependencies", "prj_primary"], usedBy: ["prj_index", "prj_storage"],
            fx: T("none: valor inmutable.", "none: immutable value."),
            rel: T("Es «el proyecto» como dato: sus áreas y su artefacto principal.", "It is 'the project' as data: its areas and primary artifact."),
